import { useEffect, useState } from 'react'
import { Truck } from 'lucide-react'
import { deliveryApi, type Delivery, supplierApi, type Supplier, type Vendor } from '../../api'
import { Button } from '../../components/ui/button'
import { Card, CardContent } from '../../components/ui/card'
import { Input } from '../../components/ui/input'

export function DeliveryPage({ vendor, storeId }: { vendor?: Vendor; storeId?: number }) { const [deliveries, setDeliveries] = useState<Delivery[]>([]); const [suppliers, setSuppliers] = useState<Supplier[]>([]); const [supplierName, setSupplierName] = useState(''); const [message, setMessage] = useState(''); const load = () => { if (vendor && storeId) deliveryApi.list(vendor.id, storeId).then(setDeliveries).catch(() => setDeliveries([])); if (vendor) supplierApi.list(vendor.id).then(setSuppliers).catch(() => setSuppliers([])) }; useEffect(load, [vendor, storeId]); async function createSupplier() { if (!vendor || !supplierName.trim()) return; try { const supplier = await supplierApi.create(vendor.id, supplierName); setSuppliers(current => [...current, supplier]); setSupplierName(''); setMessage('Supplier added.') } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to add supplier.') } } async function update(delivery: Delivery, status: string) { if (!vendor || !storeId) return; try { if (status === 'RECEIVED') await deliveryApi.receive(vendor.id, storeId, delivery.id); else await deliveryApi.status(vendor.id, storeId, delivery.id, status); load() } catch (error) { setMessage(error instanceof Error ? error.message : 'Unable to update delivery.') } } return <><PageIntro title="Deliveries" text="Track supplier deliveries from upcoming to received and completed." />{message && <p className="mb-4 rounded-xl bg-indigo-50 p-3 text-sm font-semibold text-indigo-700">{message}</p>}<div className="grid gap-5 xl:grid-cols-[1fr_300px]"><Card><CardContent className="p-4"><div className="space-y-3">{deliveries.map(delivery => <div key={delivery.id} className="flex flex-col justify-between gap-3 rounded-xl border border-slate-100 p-4 sm:flex-row sm:items-center"><div><strong className="block text-sm">{delivery.supplierName}</strong><span className="text-xs text-slate-500">Expected {delivery.expectedDate} · {delivery.items.length} products</span></div><div className="flex items-center gap-2"><span className="rounded-full bg-slate-100 px-2.5 py-1 text-[10px] font-bold">{delivery.status}</span>{delivery.status !== 'RECEIVED' && delivery.status !== 'COMPLETED' && <Button size="sm" onClick={() => update(delivery, delivery.status === 'UPCOMING' ? 'IN_TRANSIT' : 'RECEIVED')}>{delivery.status === 'UPCOMING' ? 'Mark in transit' : 'Receive'}</Button>}</div></div>)}{!deliveries.length && <div className="grid place-items-center p-12 text-center"><Truck className="mb-3 text-slate-300" size={30} /><p className="text-sm text-slate-500">No deliveries found.</p></div>}</div></CardContent></Card><Card><CardContent className="p-5"><h2 className="font-bold">Suppliers</h2><div className="mt-3 flex gap-2"><Input placeholder="Supplier name" value={supplierName} onChange={event => setSupplierName(event.target.value)} /><Button size="sm" onClick={createSupplier}>Add</Button></div><div className="mt-4 space-y-2">{suppliers.map(supplier => <div key={supplier.id} className="rounded-lg bg-slate-50 p-3 text-sm font-semibold">{supplier.name}</div>)}</div></CardContent></Card></div></> }
function PageIntro({ title, text }: { title: string; text: string }) { return <div className="mb-6"><p className="text-[11px] font-bold uppercase tracking-[.17em] text-indigo-600">Receiving workflow</p><h1 className="mt-1.5 text-3xl font-black tracking-[-.055em]">{title}</h1><p className="mt-2 text-[13px] text-slate-500">{text}</p></div> }
